+      { name: "Studio Chair", meta: "Bouclé / oak frame", price: "$248", image: "https://images.unsplash.com/photo-1505693416388-ac5ce068fe85?auto=format&fit=crop&w=901&q=80" },
+      { name: "Everyday Tote", meta: "Waxed canvas / leather trim", price: "$64", image: "https://images.unsplash.com/photo-1521572267360-ee0c2909d518?auto=format&fit=crop&w=900&q=80" }
+    ];
+
+    const deals = [
+      { title: "Weekend refresh", copy: "Save on lighting and textiles.", price: "Up to 30% off", image: "https://images.unsplash.com/photo-1513694203232-719a280e022f?auto=format&fit=crop&w=600&q=80" },
+      { title: "Bundle picks", copy: "Mix-and-match home essentials.", price: "2 for $75", image: "https://images.unsplash.com/photo-1484101403633-562f891dc89a?auto=format&fit=crop&w=600&q=80" },
+      { title: "Member favorite", copy: "Limited run ceramics.", price: "From $22", image: "https://images.unsplash.com/photo-1517705008128-361805f42e86?auto=format&fit=crop&w=600&q=80" }
+    ];
+
+    const app = document.getElementById("app");
+
+    const productCards = products.map(product => `
+      <article class="product-card">
+        <div class="product-photo" style="background-image:url('${product.image}')"></div>
+        <div class="product-body">
+          <div class="title">${product.name}</div>
+          <div class="meta">${product.meta}</div>
+          <div class="product-footer">
+            <strong>${product.price}</strong>
+            <button class="small-btn">Shop</button>
+          </div>
+        </div>
+      </article>
+    `).join("");
+
+    const dealCards = deals.map(deal => `
+      <article class="deal-item">
+        <div class="deal-thumb" style="background-image:url('${deal.image}')"></div>
+        <div class="deal-copy">
+          <strong>${deal.title}</strong>
+          <div class="meta">${deal.copy}</div>
+        </div>
+        <div class="deal-price">${deal.price}</div>
+      </article>
+    `).join("");
+
+    app.innerHTML = `
+      <div class="shell">
+        <header class="topbar">
+          <div class="brand">
+            <div class="brand-mark">N</div>
+            <div>
+              <div>Northstar Market</div>
+              <small style="color:var(--muted); font-weight:500;">Modern retail essentials</small>
+            </div>
+          </div>
+          <nav class="nav" aria-label="Main">
+            <a href="#featured">Featured</a>
+            <a href="#deals">Deals</a>
+            <a href="#editorial">Journal</a>
+          </nav>
+          <div class="actions">
+            <button class="ghost">Search</button>
+            <button class="pill">Cart (2)</button>
+          </div>
+        </header>
+
+        <main>
+          <section class="hero">
+            <div class="hero-copy">
+              <div>
+                <div class="eyebrow">New season / curated retail</div>
+                <h1>Design-led essentials for a better home.</h1>
+                <p class="lead">Discover elevated products, timely offers, and editorial stories that make shopping feel thoughtful and fresh.</p>
+                <div class="cta-row">
+                  <a class="btn btn-primary" href="#featured">Shop featured</a>
+                  <a class="btn btn-secondary" href="#editorial">Read journal</a>
+                </div>
+              </div>
+              <div class="stats" aria-label="Store highlights">
+                <div class="stat"><strong>120+</strong><span>curated products</span></div>
+                <div class="stat"><strong>48h</strong><span>fast dispatch</span></div>
+                <div class="stat"><strong>4.9/5</strong><span>customer rating</span></div>
+              </div>
+            </div>
+
+            <aside class="hero-aside">
+              <div class="feature-panel product-spotlight">
+                <span class="badge">Spotlight</span>
+                <div class="spotlight-img"></div>
+                <div class="spotlight-meta">
+                  <div>
+                    <strong>Signature Accent Chair</strong>
+                    <div class="meta">Soft texture, sculpted silhouette</div>
+                  </div>
+                  <div class="price">$340</div>
+                </div>
+              </div>
+              <div class="feature-panel">
+                <strong>Free shipping</strong>
+                <p style="margin:8px 0 0; color:var(--muted);">On orders over $75 with easy 30-day returns.</p>
+              </div>
+            </aside>
+          </section>
+
+          <section class="grid">
+            <article id="featured" class="section-card featured">
+              <div class="section-head">
+                <div>
+                  <span class="badge">Featured products</span>
+                  <h2 style="margin-top:10px;">Best sellers with timeless appeal.</h2>
+                </div>
+                <p>High-impact pieces chosen for everyday use.</p>
+              </div>
+              <div class="product-grid">
+                ${productCards}
+              </div>
+            </article>
+
+            <article id="deals" class="section-card deals">
+              <div class="section-head" style="display:block;">
+                <span class="badge">Deals</span>
+                <h3 style="margin-top:10px;">Promotions worth checking first.</h3>
+                <p>Simple offers with clear value.</p>
+              </div>
+              <div class="deal-list">
+                ${dealCards}
+              </div>
+            </article>
+
+            <article id="editorial" class="section-card editorial">
+              <div class="section-head">
+                <div>
+                  <span class="badge">Editorial content</span>
+                  <h2 style="margin-top:10px;">Stories that help customers shop with confidence.</h2>
+                </div>
+                <p>Guides, trends, and product care.</p>
+              </div>
+              <div class="editorial-grid">
+                <div class="story">
+                  <div>
+                    <div class="eyebrow" style="color:#ffd7c2;">Style guide</div>
+                    <h3>How to layer neutral tones without losing warmth.</h3>
+                    <p>Our editors break down texture, scale, and color balance for a polished everyday space.</p>
+                  </div>
+                </div>
+                <div class="notes">
+                  <div class="note">
+                    <small>Trend report</small>
+                    <h4>Rounded edges are taking over living spaces.</h4>
+                    <p>See the pieces customers are pairing with soft silhouettes and natural finishes.</p>
+                  </div>
+                  <div class="note">
+                    <small>Care tips</small>
+                    <h4>Keep favorites looking new for longer.</h4>
+                    <p>Quick guidance for cleaning textiles, wood, and ceramics at home.</p>
+                  </div>
+                </div>
+              </div>
+            </article>
+          </section>
+        </main>
+
+        <footer>
+          <div>Northstar Market · Curated retail for modern living</div>
+          <div>Shipping · Returns · Support</div>
+        </footer>
+      </div>
+    `;
+  </script>
+</body>
+</html>
*** End Patch
